describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100
        new FixedAmountDiscountPolicy(200), // 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative individual results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, which is max(0, 0) = 0
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // subtotal = 1000, 10% of 1000 = 100 → remaining 900, then fixed 200 → total discount = 300
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering affects the result in chain mode", () => {
      // fixed 200 first on 1000 → remaining 800, then 10% of 800 = 80 → total 280
      const policies = [
        new FixedAmountDiscountPolicy(200),
        new PercentageDiscountPolicy(10),
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(280);
    });

    it("stops accumulating when remaining hits 0", () => {
      // 100% off 1000 → remaining 0, fixed 200 on 0 → 0
      const policies = [
        new PercentageDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("default stacking mode is sum", () => {
    it("defaults to sum when mode is omitted", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      // sum: 10% of 1000 = 100 + 50 = 150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });
});

