import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2500 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };

      const result = await cart.checkout({ priceFetcher });
      // Updated price: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("w1");
    });

    it("throws RangeError when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws when fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "service down",
      );
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
    });

    it("throws InventoryError when item is not available", async () => {
      const cart = new Cart();
      cart.add(widget, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );

      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("w1");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
        expect(err.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial (available: true but quantity insufficient)", async () => {
      const cart = new Cart();
      cart.add(widget, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });

    it("uses default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(widget, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("w1");
      }
    });

    it("checks first item first; stops at first denial", async () => {
      const cart = new Cart();
      cart.add(widget, 1);
      cart.add(gadget, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: false, reason: "out of stock" })
          .mockResolvedValueOnce({ available: true }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
      // Should stop after the first denial
      expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US" });
      cart.add(widget, 1); // subtotal 1000
      const result = await cart.checkout({ asyncTaxProvider });
      // 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(widget, 1); // subtotal 1000, discount 200, taxable 800
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(80); // 10% of 800
    });

    it("propagates async tax provider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      const cart = new Cart();
      cart.add(widget, 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(widget, 2);

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed price: 2000 * 2 = 4000
      expect(result.totals.subtotalCents).toBe(4000);
      // Discount: 10% of 4000 = 400
      expect(result.totals.discountCents).toBe(400);
      // Tax: 8% of (4000 - 400) = 8% of 3600 = 288
      expect(result.totals.taxCents).toBe(288);
      // Shipping: flat 500
      expect(result.totals.shippingCents).toBe(500);
      // Total: 3600 + 288 + 500 = 4388
      expect(result.totals.totalCents).toBe(4388);
    });

    it("returns lines with refreshed prices", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const cart = new Cart();
      cart.add(widget, 1);

      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0].product.unitPriceCents).toBe(1500);
    });

    it("works without any collaborators (sync fallback)", async () => {
      const cart = new Cart();
      cart.add(widget, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.totalCents).toBe(2000);
    });
  });

  describe("InventoryError shape", () => {
    it("has correct name and properties", () => {
      const err = new InventoryError("out of stock", "p1", 5, 2);
      expect(err.name).toBe("InventoryError");
      expect(err.productId).toBe("p1");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err.message).toBe("out of stock");
      expect(err).toBeInstanceOf(Error);
    });

    it("supports undefined available", () => {
      const err = new InventoryError("gone", "p2", 3, undefined);
      expect(err.available).toBeUndefined();
    });
  });
});

