toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const sampleLine: CartLine = {
  product: { id: "p1", name: "Widget", unitPriceCents: 1000, weightGrams: 500 },
  quantity: 1,
};

const heavyLine: CartLine = {
  product: { id: "p2", name: "Heavy", unitPriceCents: 2000, weightGrams: 3000 },
  quantity: 2,
};

const weightlessLine: CartLine = {
  product: { id: "p3", name: "Digital", unitPriceCents: 500 },
  quantity: 1,
};

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([sampleLine], 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts valid params", () => {
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns flat fee for non-empty cart without threshold", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([sampleLine], 1000)).toBe(500);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([sampleLine], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([sampleLine], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([sampleLine], 4999)).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflow", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 200 },
              { upToGrams: 2000, costCents: 500 },
            ],
            800,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 200 },
      { upToGrams: 2000, costCents: 500 },
      { upToGrams: 5000, costCents: 900 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 for cart with zero-weight items", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([weightlessLine], 500)).toBe(0);
    });

    it("selects first bracket when weight <= lowest upToGrams", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // sampleLine: 500g * 1 = 500g → bracket[0] (upTo 500)
      expect(calc.computeShippingCents([sampleLine], 1000)).toBe(200);
    });

    it("selects middle bracket at boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g to 2000g → bracket[1]
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 501 },
        quantity: 1,
      };
      expect(calc.computeShippingCents([line], 100)).toBe(500);
    });

    it("selects highest bracket for heavy items within range", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // heavyLine: 3000g * 2 = 6000g → overflow
      // but first a 4000g item → bracket[2]
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 4000 },
        quantity: 1,
      };
      expect(calc.computeShippingCents([line], 100)).toBe(900);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 1500);
      // heavyLine: 3000g * 2 = 6000g > 5000
      expect(calc.computeShippingCents([heavyLine], 2000)).toBe(1500);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000, no overflow specified → uses bracket[2].costCents = 900
      expect(calc.computeShippingCents([heavyLine], 2000)).toBe(900);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 900 },
        { upToGrams: 500, costCents: 200 },
        { upToGrams: 2000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(calc.computeShippingCents([sampleLine], 1000)).toBe(200);
    });
  });
});

