import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a product with the given quantity", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding the same product twice", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      cart.add(widget, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(widget, 0)).toThrow(RangeError);
      expect(() => cart.add(widget, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(widget, 1);
      expect(cart.remove(widget.id)).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      cart.updateQuantity(widget.id, 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      cart.updateQuantity(widget.id, 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(widget, 1);
      expect(() => cart.updateQuantity(widget.id, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(widget, 1);
      expect(() => cart.updateQuantity(widget.id, 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      cart.add(gadget, 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(widget, 2); // 2000
      cart.add(gadget, 1); // 2500
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4500);
    });

    it("applies discount policy and clamps to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(widget, 1); // subtotal 1000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(totals.subtotalCents).toBe(1000);
    });

    it("clamps over-subtotal discount to subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(widget, 1); // subtotal 1000
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(widget, 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
      cart.add(widget, 1); // subtotal 1000, discount 200, taxable 800
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
    });

    it("uses configured region for tax", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(widget, 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("computes shipping on lines and discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(499),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(widget, 1); // subtotal 1000, discounted 700
      cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700,
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const tax: TaxCalculator = {
        computeTaxCents: () => 72,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(widget, 1); // subtotal 1000
      const totals = cart.totals();
      // discounted = 900, tax = 72, shipping = 500
      expect(totals.totalCents).toBe(900 + 72 + 500);
    });

    it("empty cart yields all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });
  });
});

